<script setup lang="ts">
import ProductionDeviceManager from '~/components/ProductionDeviceManager.vue'
definePageMeta({layout:'admin',middleware:'backend-guard',keepalive:true})
useHead({title:'生产任务'})
const {canManageUsers}=useUser(),toast=useToast()
const filters=reactive({keyword:'',lineName:'',operatorId:'',status:'',dateFrom:'',dateTo:''}),keyword=ref(''),page=ref(1)
const {data,pending,error,refresh}=await useFetch<any>('/api/admin/production-lines',{query:computed(()=>({...filters,page:page.value}))})
const fileKeyword=ref(''),fileSearch=ref('')
const {data:options,pending:optionBusy,refresh:refreshOptions}=await useFetch<any>('/api/admin/production-lines/options',{query:{keyword:fileKeyword}})
watch(keyword,(value,_,cleanup)=>{const timer=setTimeout(()=>{filters.keyword=value.trim();page.value=1},300);cleanup(()=>clearTimeout(timer))})
watch(fileSearch,(value,_,cleanup)=>{const timer=setTimeout(()=>fileKeyword.value=value.trim(),300);cleanup(()=>clearTimeout(timer))})
watch(()=>JSON.stringify(filters),()=>{page.value=1})
const operatorOptions=computed(()=>(options.value?.operators||[]).map((p:any)=>({label:`${p.name} · ${p.username}`,value:String(p.id)})))
const lineOptions=computed(()=>(options.value?.lines||[]).map((name:string)=>({label:name,value:name})))
const sourceOptions=computed(()=>(options.value?.uploads||[]).map((u:any)=>({value:String(u.id),label:`${u.file_name} · ${u.product_name} · ${u.total}个码 · ${u.enterprise_name}`})))
const statuses=[{label:'全部状态',value:'all'},{label:'进行中',value:'active'},{label:'已结束',value:'completed'},{label:'历史任务',value:'history'}]
const showDevices=ref(false),showForm=ref(false),busy=ref(false),editing=ref<any>(null),requestId=ref(crypto.randomUUID())
const form=ref({name:'',lineName:'',sourceUploadBatchId:'',operatorIds:[] as string[]})
const selectedUpload=computed(()=>(options.value?.uploads||[]).find((u:any)=>String(u.id)===form.value.sourceUploadBatchId))
const selectedEnterprise=computed(()=>editing.value?.enterprise_id||selectedUpload.value?.enterprise_id)
const workerOptions=computed(()=>(options.value?.operators||[]).filter((p:any)=>Number(p.enterprise_id)===Number(selectedEnterprise.value)).map((p:any)=>({label:`${p.name} · ${p.username}`,value:String(p.id)})))
watch(()=>form.value.sourceUploadBatchId,()=>{if(!editing.value)form.value.operatorIds=[]})
watch(()=>JSON.stringify(form.value),()=>{if(!busy.value)requestId.value=crypto.randomUUID()})
function resetSearch(){keyword.value='';Object.assign(filters,{keyword:'',lineName:'',operatorId:'',status:'',dateFrom:'',dateTo:''});page.value=1}
function openCreate(){editing.value=null;form.value={name:'',lineName:'',sourceUploadBatchId:'',operatorIds:[]};requestId.value=crypto.randomUUID();showForm.value=true;void refreshOptions()}
function openEdit(t:any){editing.value=t;form.value={name:t.name,lineName:t.line_name,sourceUploadBatchId:String(t.source_upload_id||''),operatorIds:(t.operators||[]).filter((p:any)=>!p.removed_at).map((p:any)=>String(p.user_id))};showForm.value=true}
async function save(){if(busy.value)return;if(!form.value.operatorIds.length){toast.add({title:'请选择这条线的生产操作员',color:'warning'});return}busy.value=true;try{const body={...form.value,sourceUploadBatchId:Number(form.value.sourceUploadBatchId),operatorIds:form.value.operatorIds.map(Number),requestId:requestId.value};if(editing.value)await $fetch('/api/admin/production-lines/'+editing.value.id,{method:'PATCH',body:{...body,action:'edit'}});else await $fetch('/api/admin/production-lines',{method:'POST',body});showForm.value=false;await refresh();await refreshOptions();toast.add({title:'任务已保存',color:'success'})}catch(e:any){toast.add({title:e?.data?.statusMessage||'保存未确认，请使用原内容重试',color:'error'})}finally{busy.value=false}}
const details=ref<Record<number,boolean>>({}),codeTask=ref<any>(null),showCodes=ref(false),codePage=ref(1),codeState=ref(''),codeKeyword=ref('')
const {data:codeData,pending:codeBusy,refresh:refreshCodes}=await useFetch<any>(()=>codeTask.value?`/api/admin/production-tasks/${codeTask.value.id}`:'/api/admin/production-lines',{immediate:false,query:{page:codePage,state:codeState,keyword:codeKeyword}})
async function openCodes(t:any){codeTask.value=t;codePage.value=1;codeState.value='';codeKeyword.value='';showCodes.value=true;await refreshCodes()}
watch([codePage,codeState,codeKeyword],()=>{if(showCodes.value)void refreshCodes()})
const finishTarget=ref<any>(null),showFinish=ref(false),recordsComplete=ref(false)
function openFinish(t:any){finishTarget.value=t;recordsComplete.value=false;showFinish.value=true}
async function finish(){if(!recordsComplete.value||busy.value)return;busy.value=true;try{await $fetch('/api/admin/production-lines/'+finishTarget.value.id,{method:'PATCH',body:{action:'complete',recordsComplete:true}});showFinish.value=false;await refresh();toast.add({title:'生产任务已结束，采集历史已保留',color:'success'})}catch(e:any){toast.add({title:e?.data?.statusMessage||'结束未确认，请重试',color:'error'})}finally{busy.value=false}}
const selectedIds=ref<number[]>([]),deleteTargets=ref<any[]>([]),showDelete=ref(false)
const removableRows=computed(()=>(data.value?.rows||[]).filter((t:any)=>t.can_delete))
const allSelected=computed(()=>removableRows.value.length>0&&removableRows.value.every((t:any)=>selectedIds.value.includes(Number(t.id))))
function toggleSelected(id:number,checked:boolean){selectedIds.value=checked?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(n=>n!==id)}
function togglePage(checked:boolean){selectedIds.value=checked?removableRows.value.map((t:any)=>Number(t.id)):[]}
watch(()=>JSON.stringify({...filters,page:page.value}),()=>{selectedIds.value=[]})
watch(data,()=>{const ids=new Set(removableRows.value.map((t:any)=>Number(t.id)));selectedIds.value=selectedIds.value.filter(id=>ids.has(id))})
function openDelete(tasks:any[]){if(!tasks.length||busy.value)return;deleteTargets.value=tasks.map(t=>({...t}));showDelete.value=true}
function openBulkDelete(){openDelete((data.value?.rows||[]).filter((t:any)=>selectedIds.value.includes(Number(t.id))))}
async function removeTasks(){
 if(busy.value||!deleteTargets.value.length)return
 busy.value=true
 try{
  const ids=deleteTargets.value.map(t=>Number(t.id))
  const result=ids.length===1?await $fetch<any>('/api/admin/production-tasks/'+ids[0],{method:'DELETE'}):await $fetch<any>('/api/admin/production-tasks',{method:'DELETE',body:{ids}})
  showDelete.value=false;selectedIds.value=[]
  for(const id of ids)delete details.value[id]
  if(ids.includes(Number(codeTask.value?.id)))showCodes.value=false
  await refresh();await refreshOptions()
  if(page.value>1&&!data.value?.rows?.length){page.value=Math.max(1,Math.ceil(Number(data.value?.total||0)/20))}
  toast.add({title:result.deletedCount?`已删除 ${result.deletedCount} 个任务，追溯历史已保留`:'任务已删除，追溯历史已保留',color:'success'})
 }catch(e:any){toast.add({title:e?.data?.statusMessage||'删除未确认，请刷新后重试',color:'error'})}finally{busy.value=false}
}
const time=(v:any)=>v?String(v).replace('T',' ').slice(0,19):'-'
const clock=(ms:any,fallback:any)=>ms?new Date(Number(ms)).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai',hour12:false}):time(fallback)
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(document.visibilityState==='visible'&&!showForm.value&&!showFinish.value&&!showDelete.value)void refresh()},20000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <div class="space-y-4">
  <div class="flex flex-wrap justify-between items-center gap-3"><div><h1 class="b-page-title">生产任务</h1><p class="b-page-desc">整份入库码文件对应生产任务，安排本厂操作员，查看每条生产线的人员和扫码进度。</p></div><div class="flex gap-2"><UButton v-if="canManageUsers" color="error" variant="outline" :disabled="!selectedIds.length||busy" @click="openBulkDelete">批量删除<span v-if="selectedIds.length">（{{ selectedIds.length }}）</span></UButton><UButton v-if="canManageUsers" variant="outline" @click="showDevices=!showDevices">设备管理</UButton><UButton v-if="canManageUsers" @click="openCreate">新建任务</UButton></div></div>
  <div v-if="showDevices&&canManageUsers" class="b-card p-5"><ProductionDeviceManager /></div>
  <div class="b-card p-5 space-y-4">
   <form class="flex flex-wrap items-end gap-3" @submit.prevent="filters.keyword=keyword.trim();refresh()"><label class="min-w-64 flex-1"><span class="block mb-1 text-sm">模糊搜索</span><UInput v-model="keyword" placeholder="任务、产品、生产线、文件、员工姓名或工号" class="w-full" /></label><label><span class="block mb-1 text-sm">创建日期从</span><input v-model="filters.dateFrom" type="date" class="rounded border p-2" /></label><label><span class="block mb-1 text-sm">至</span><input v-model="filters.dateTo" type="date" class="rounded border p-2" /></label><UButton type="submit">查询</UButton><UButton variant="outline" @click="resetSearch">重置</UButton><UButton variant="outline" :loading="pending" @click="refresh()">刷新</UButton></form>
   <p class="text-sm text-muted">表头下拉支持搜索生产线或操作员。进度显示服务器已收到的数据；离线记录上传或TXT导入后补齐。</p>
   <p v-if="error" class="text-error">查询失败，请重试。</p><p v-else-if="pending&&!data?.rows">正在加载…</p>
   <div class="task-table-wrap"><table class="b-table task-table"><colgroup><col v-if="canManageUsers" class="selection-column"><col><col><col class="line-column"><col><col class="stats-column"><col class="time-column"><col class="status-column"><col class="actions-column"></colgroup><thead><tr><th v-if="canManageUsers" class="task-selection-cell"><input type="checkbox" aria-label="选择当前页可删除任务" :checked="allSelected" :indeterminate="selectedIds.length>0&&!allSelected" :disabled="!removableRows.length||busy" @change="togglePage(($event.target as HTMLInputElement).checked)"></th><th>任务 / 入库文件</th><th>产品</th><th><span class="block mb-1">生产线</span><USelectMenu v-model="filters.lineName" :items="lineOptions" value-key="value" placeholder="全部" aria-label="按生产线筛选" class="w-full min-w-0" size="xs" :clear="true" :search-input="{placeholder:'搜索生产线'}" /></th><th><span class="block mb-1">操作员 / 扫码情况</span><USelectMenu v-model="filters.operatorId" :items="operatorOptions" value-key="value" placeholder="全部操作员" class="w-full min-w-0" :clear="true" :search-input="{placeholder:'姓名或工号'}" /></th><th>扫码统计</th><th>开始 / 停止时间</th><th><span class="block mb-1">状态</span><USelect v-model="filters.status" :items="statuses" value-key="value" placeholder="全部" aria-label="按状态筛选" class="w-full min-w-0" size="xs" /></th><th class="task-actions-cell">操作</th></tr></thead>
    <tbody><template v-for="t in data?.rows||[]" :key="t.id"><tr class="task-row"><td v-if="canManageUsers" class="task-selection-cell" data-label="选择任务"><input type="checkbox" :aria-label="`选择任务 ${t.name}`" :title="t.can_delete?'选择任务':'请先结束任务并收齐采集记录'" :checked="selectedIds.includes(Number(t.id))" :disabled="!t.can_delete||busy" @change="toggleSelected(Number(t.id),($event.target as HTMLInputElement).checked)"></td><td data-label="任务 / 入库文件"><strong>{{ t.name }}</strong><p class="text-sm text-muted break-all">{{ t.file_name||'历史任务' }}</p></td><td data-label="产品"><strong>{{ t.product_name||'-' }}</strong><p v-if="t.product_spec_name" class="text-sm text-muted">{{ t.product_spec_name }}</p><p v-if="t.registration_no" class="text-xs text-muted">{{ t.registration_no }}</p></td><td data-label="生产线">{{ t.line_name||'-' }}</td><td data-label="操作员 / 扫码情况"><div v-for="p in t.operators||[]" :key="p.user_id" class="mb-2"><strong>{{ p.name }}</strong><span class="text-sm text-muted"> · {{ p.username }}{{ p.removed_at?'（原参与人员）':'' }}</span><p class="text-sm">有效 {{ Number(p.collected)||0 }} · 重复 {{ Number(p.duplicates)||0 }} · 异常 {{ Number(p.exceptions)||0 }}</p><p class="text-xs text-muted">开始 {{ clock(p.started_ms,p.started_at) }}<br>停止 {{ p.active_sessions?'采集中 / 待结束同步':clock(p.stopped_ms,p.stopped_at) }}</p></div><span v-if="!t.operators?.length" class="text-muted">历史任务未安排个人工号</span></td><td data-label="扫码统计"><div class="task-stats"><span>码数 <strong>{{ t.total }}</strong></span><span>有效 <strong>{{ t.collected }}</strong></span><span>重复 {{ t.duplicates }} / 异常 {{ t.exceptions }}</span></div></td><td data-label="开始 / 停止时间">{{ clock(t.started_ms,t.started_at) }}<br>{{ t.active_sessions?'有人采集或待结束同步':clock(t.stopped_ms,t.stopped_at||t.ended_at) }}</td><td data-label="状态"><span v-if="t.workflow!=='line-team'" class="b-tag">历史任务</span><span v-else :class="t.status==='active'?'b-tag-success':'b-tag'">{{ t.status==='active'?'进行中':'已结束' }}</span></td><td class="task-actions-cell" data-label="操作"><div class="task-actions"><UButton size="sm" variant="outline" @click="details[t.id]=!details[t.id]">{{ details[t.id]?'收起详情':'员工详情' }}</UButton><UButton size="sm" variant="outline" @click="openCodes(t)">码明细</UButton><template v-if="canManageUsers&&t.workflow==='line-team'&&t.status==='active'"><UButton size="sm" variant="outline" @click="openEdit(t)">编辑人员</UButton><UButton size="sm" color="warning" variant="outline" @click="openFinish(t)">结束任务</UButton></template><UButton v-if="canManageUsers" size="sm" icon="i-lucide-trash-2" color="error" variant="outline" :aria-label="`删除任务 ${t.name}`" :title="t.can_delete?'删除任务':'请先结束任务并收齐采集记录'" :disabled="!t.can_delete||busy" @click="openDelete([t])" /></div></td></tr><tr v-if="details[t.id]" class="task-details-row"><td :colspan="canManageUsers?9:8" class="bg-elevated"><ProductionWorkerProgress :task-id="t.id" /></td></tr></template><tr v-if="!pending&&!data?.rows?.length"><td :colspan="canManageUsers?9:8" class="text-center py-8 text-muted">暂无符合条件的任务</td></tr></tbody></table></div>
   <div class="flex items-center gap-3"><span class="text-sm text-muted">共 {{ data?.total||0 }} 个任务</span><UButton :disabled="page<=1||pending" variant="outline" @click="page--">上一页</UButton><span>第 {{ page }} 页</span><UButton :disabled="page*20>=(data?.total||0)||pending" variant="outline" @click="page++">下一页</UButton></div>
  </div>
  <UModal v-model:open="showForm" :dismissible="!busy" :close="{ 'aria-label':'关闭' }" :title="editing?'编辑任务与人员':'新建生产任务'" :ui="{content:'max-w-2xl'}"><template #body><form id="line-team-form" class="space-y-4" @submit.prevent="save"><label class="block"><span class="block mb-1">任务名称</span><UInput v-model="form.name" required maxlength="100" class="w-full" /></label><label class="block"><span class="block mb-1">生产线</span><input v-model="form.lineName" list="known-lines" required maxlength="100" placeholder="填写生产线名称" class="rounded border p-2 w-full"><datalist id="known-lines"><option v-for="line in options?.lines||[]" :key="line" :value="line" /></datalist></label><div v-if="!editing"><label class="block mb-1">已入库码文件</label><USelectMenu v-model="form.sourceUploadBatchId" v-model:search-term="fileSearch" :items="sourceOptions" value-key="value" :loading="optionBusy" ignore-filter :search-input="{placeholder:'文件名或产品名'}" placeholder="选择整份已入库码文件" class="w-full" /><p class="text-sm text-muted mt-1">{{ selectedUpload?`本任务管理文件内全部 ${selectedUpload.total} 个码，不按设备分码。`:'请选择尚未生产、尚未归入其他任务的完整码文件。' }}</p></div><div><label class="block mb-1">选择工作在这条线的生产操作员</label><USelectMenu v-model="form.operatorIds" :items="workerOptions" multiple value-key="value" :disabled="!selectedEnterprise" :search-input="{placeholder:'搜索姓名或工号'}" placeholder="可选择多名操作员" class="w-full" /><p class="text-sm text-muted mt-1">账号来自系统设置中的“生产操作员”，仅可选择码文件所属厂家的人员。</p></div></form></template><template #footer><UButton type="submit" form="line-team-form" :loading="busy" :disabled="!form.operatorIds.length||(!editing&&!selectedUpload)">保存任务</UButton><UButton variant="outline" :disabled="busy" @click="showForm=false">取消</UButton></template></UModal>
  <UModal v-model:open="showFinish" title="结束生产任务" :dismissible="!busy" :close="{ 'aria-label':'关闭' }"><template #body><p class="mb-3">{{ finishTarget?.name }} · {{ finishTarget?.line_name }}</p><p class="mb-3">所有参与工人须在手机点击“结束采集”，并将完整记录和结束标记上传。服务器会检查已登记会话；尚未联网登记的离线设备，需要人工确认记录已收齐。</p><p v-if="Number(finishTarget?.collected)<Number(finishTarget?.total)" class="mb-3 text-warning">当前已上传有效扫码 {{ finishTarget?.collected }} / {{ finishTarget?.total }}。文件内尚有未扫描或未上传记录，请先核实是否确实结束本次工作。</p><label class="flex gap-2 items-start"><input v-model="recordsComplete" type="checkbox" class="mt-1"><span>我已确认所有参与人员都已结束采集，自动上传或离线TXT记录已经收齐。</span></label></template><template #footer><UButton color="warning" :disabled="!recordsComplete" :loading="busy" @click="finish">确认结束任务</UButton><UButton variant="outline" :disabled="busy" @click="showFinish=false">取消</UButton></template></UModal>
  <UModal v-model:open="showDelete" :title="deleteTargets.length===1?'删除生产任务':'批量删除生产任务'" :dismissible="!busy" :close="false"><template #body><p class="mb-3">确认删除以下 {{ deleteTargets.length }} 个任务？</p><ul class="mb-3 max-h-60 overflow-y-auto space-y-2"><li v-for="t in deleteTargets" :key="t.id"><strong>{{ t.name }}</strong> · {{ t.line_name||'-' }}</li></ul><p class="text-sm text-muted">删除后任务不再出现在列表中。追溯码、生产资料、人员和设备扫码历史完整保留；已领用码不会释放或再次分配。</p><p v-if="deleteTargets.length>1" class="mt-2 text-sm text-muted">所有所选任务必须符合删除条件；任一任务不能删除时，整批保持原样。</p></template><template #footer><UButton color="error" :loading="busy" :disabled="busy" @click="removeTasks">确认删除</UButton><UButton variant="outline" :disabled="busy" @click="showDelete=false">取消</UButton></template></UModal>
  <UModal v-model:open="showCodes" :title="(codeTask?.name||'')+' · 码明细'" :close="{ 'aria-label':'关闭' }" :ui="{content:'max-w-5xl'}"><template #body><div class="space-y-3"><div class="flex flex-wrap gap-3"><UInput v-model="codeKeyword" placeholder="追溯码模糊查询" /><select v-model="codeState" class="rounded border p-2"><option value="">全部</option><option value="used">已扫码</option><option value="reserved">未扫描</option></select></div><p v-if="codeBusy">正在加载…</p><div class="overflow-x-auto"><table class="b-table"><thead><tr><th>追溯码</th><th>采集情况</th><th>操作员</th><th>设备 / 采集时间</th></tr></thead><tbody><tr v-for="c in codeData?.rows||[]" :key="c.code_id"><td class="font-mono">{{ c.code }}</td><td>{{ c.state==='used'?'已扫码':'未扫描' }}</td><td>{{ c.operator_name||'-' }}</td><td>{{ c.device||'-' }}<br>{{ time(c.used_at) }}</td></tr></tbody></table></div><div class="flex gap-3"><UButton :disabled="codePage<=1" variant="outline" @click="codePage--">上一页</UButton><span>第 {{ codePage }} 页，共 {{ codeData?.filteredTotal||0 }} 个码</span><UButton :disabled="codePage*100>=(codeData?.filteredTotal||0)" variant="outline" @click="codePage++">下一页</UButton></div></div></template></UModal>
 </div>
</template>
<style scoped>
.task-table{width:100%;min-width:0;table-layout:fixed}
.task-table .selection-column{width:36px}.task-selection-cell{text-align:center!important}.task-selection-cell input{width:18px;height:18px;accent-color:var(--ui-primary);cursor:pointer}.task-selection-cell input:disabled{cursor:not-allowed}
.task-table .line-column{width:88px}.task-table .stats-column{width:112px}.task-table .time-column{width:144px}.task-table .status-column{width:88px}.task-table .actions-column{width:348px}
.b-table th,.b-table td{padding:.75rem .6rem;vertical-align:top}.b-table tbody tr{border-top:1px solid var(--b-divider)}.b-table th{text-align:left}
.task-table > tbody > tr > td{font-size:15px;overflow-wrap:anywhere;white-space:normal}
.task-actions-cell{white-space:nowrap}.task-actions{display:inline-flex;align-items:center;flex-wrap:nowrap;gap:.25rem;white-space:nowrap}.task-actions :deep(button){flex-shrink:0;white-space:nowrap;padding-inline:.5rem}
.task-stats{display:grid;gap:.25rem;font-size:14px}.task-stats strong{font-variant-numeric:tabular-nums}
@media(max-width:1200px){
 .task-table,.task-table > tbody{display:block}.task-table > colgroup,.task-table > thead{display:none}
 .task-table > tbody > .task-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding:.75rem 0;gap:.5rem}
 .task-table > tbody > .task-row > td{display:block;width:auto}
 .task-table > tbody > .task-row > td[data-label]::before{content:attr(data-label);display:block;margin-bottom:.35rem;font-size:12px;color:var(--b-text-muted)}
 .task-table > tbody > .task-row > .task-actions-cell,.task-table > tbody > .task-row > .task-selection-cell{grid-column:1/-1}
 .task-table > tbody > .task-row > .task-selection-cell{display:flex;align-items:center;gap:.5rem;text-align:left!important}
 .task-table > tbody > .task-details-row,.task-table > tbody > .task-details-row > td{display:block;width:100%}
}
</style>
